import"./chunk-ZW5NV4UO.js";var n={vi:{title:"C\u1ED9ng \u0111\u1ED3ng Vi\u1EC7t tr\xEAn Mastodon: nh\u1EEFng t\xE0i kho\u1EA3n \u0111\u1EC3 theo d\xF5i",description:"Kh\xE1m ph\xE1 t\xE0i kho\u1EA3n ti\u1EBFng Vi\u1EC7t \u1EDF kh\u1EAFp n\u01A1i v\xE0 nh\u1EEFng ng\u01B0\u1EDDi g\u1EAFn b\xF3 v\u1EDBi Vi\u1EC7t Nam: \u0111\u1EDDi s\u1ED1ng, c\xF4ng ngh\u1EC7, \u1EA3nh, h\u1ECDc t\u1EADp v\xE0 tin t\u1EE9c.",heading:"C\u1ED9ng \u0111\u1ED3ng Vi\u1EC7t tr\xEAn Mastodon",listTitle:"C\u1ED9ng \u0111\u1ED3ng Vi\u1EC7t",intro:["T\xECm m\u1ED9t g\xF3c c\u1ED9ng \u0111\u1ED3ng Vi\u1EC7t tr\xEAn Mastodon: nh\u1EEFng c\xE2u chuy\u1EC7n \u0111\u1EDDi th\u01B0\u1EDDng, c\xF4ng ngh\u1EC7, \u1EA3nh, h\u1ECDc t\u1EADp v\xE0 tin t\u1EE9c. C\xE1c t\xE0i kho\u1EA3n vi\u1EBFt ti\u1EBFng Vi\u1EC7t c\xF3 th\u1EC3 \u1EDF Vi\u1EC7t Nam, \u1EDF n\u01B0\u1EDBc ngo\xE0i ho\u1EB7c kh\xF4ng n\xEAu n\u01A1i \u1EDF.","Danh s\xE1ch c\u0169ng c\xF3 t\xE0i kho\u1EA3n vi\u1EBFt ti\u1EBFng Anh v\u1EDBi m\u1ED1i li\xEAn h\u1EC7 r\xF5 r\xE0ng v\u1EDBi Vi\u1EC7t Nam. M\u1ED9t s\u1ED1 t\xE0i kho\u1EA3n \xEDt \u0111\u0103ng b\xE0i; m\u1ED9t s\u1ED1 l\xE0 c\u01A1 s\u1EDF gi\xE1o d\u1EE5c ho\u1EB7c d\u1ECBch v\u1EE5 th\xF4ng tin. H\xE3y xem tr\u01B0\u1EDBc v\xE0 ch\u1ECDn nh\u1EEFng g\xEC b\u1EA1n th\xEDch."],faq:[{q:"T\xF4i c\xF3 c\u1EA7n t\xE0i kho\u1EA3n kh\xF4ng?",a:"Kh\xF4ng c\u1EA7n \u0111\u1EC3 \u0111\u1ECDc h\u1ED3 s\u01A1 v\xE0 xem tr\u01B0\u1EDBc b\xE0i vi\u1EBFt c\xF4ng khai. \u0110\u0103ng nh\u1EADp Mastodon \u0111\u1EC3 theo d\xF5i ho\u1EB7c t\u1EA1o danh s\xE1ch."},{q:"M\u1ECDi ng\u01B0\u1EDDi \u0111\u1EC1u s\u1ED1ng \u1EDF Vi\u1EC7t Nam sao?",a:"Kh\xF4ng. T\xE0i kho\u1EA3n vi\u1EBFt ti\u1EBFng Vi\u1EC7t \u1EDF b\u1EA5t c\u1EE9 \u0111\xE2u \u0111\u1EC1u c\xF3 th\u1EC3 \u0111\u01B0\u1EE3c ch\u1ECDn. T\xE0i kho\u1EA3n vi\u1EBFt ti\u1EBFng Anh c\u1EA7n c\xF3 m\u1ED1i li\xEAn h\u1EC7 r\xF5 r\xE0ng v\u1EDBi Vi\u1EC7t Nam."},{q:"L\xE0m sao \u0111\u1EC3 tham gia ho\u1EB7c \u0111\u01B0\u1EE3c g\u1EE1 kh\u1ECFi danh s\xE1ch?",a:"Li\xEAn h\u1EC7 @mawkingbird@mastodon.social. T\xE0i kho\u1EA3n nh\u1ECF v\xE0 \xEDt \u0111\u0103ng b\xE0i c\u0169ng \u0111\u01B0\u1EE3c ch\xE0o \u0111\xF3n. Ch\xFAng t\xF4i t\xF4n tr\u1ECDng y\xEAu c\u1EA7u g\u1EE1 t\xEAn."}]}};export{n as COPY};
